"""Nexus IT Pack: Full-Stack Engineer Agent."""
from __future__ import annotations

from pydantic import BaseModel, Field
from nexus.providers.base import BaseModelProvider
from nexus.teams.it_pack.ba import ProductProposal
from nexus.teams.it_pack.data_architect import DataArchitecture
from nexus.teams.it_pack.designer import UiSpecification
from nexus.teams.it_pack.solution_architect import SolutionBlueprint


class FullStackSpecification(BaseModel):
    """End-to-end full-stack code generated by the Full-Stack Engineer."""
    backend_main_py: str = Field(description="Complete FastAPI service code using create_nexus_app()")
    backend_models_py: str = Field(description="Pydantic schemas and database models inheriting from NexusEntity")
    frontend_app_tsx: str = Field(description="Complete React + Tailwind application component connecting to the backend API")
    frontend_api_client_ts: str = Field(description="Type-safe TypeScript fetch client to call the backend REST endpoints")


class FullStackEngineerAgent:
    """
    Full-Stack Engineer Agent in the Nexus IT Pack.
    Builds the unified end-to-end application: FastAPI backend, database models, and React frontend.
    """

    def __init__(self, provider: BaseModelProvider) -> None:
        self.provider = provider

    def build_application(
        self,
        proposal: ProductProposal,
        solution: SolutionBlueprint,
        data_arch: DataArchitecture,
        ui_spec: UiSpecification,
    ) -> FullStackSpecification:
        """Implement complete end-to-end fullstack codebase."""
        prompt = f"""You are a Lead Full-Stack Engineer.
Implement the cohesive end-to-end codebase for:
App: {proposal.title} ({proposal.app_name})
Features: {', '.join(proposal.core_features)}
Data Tables: {', '.join(data_arch.tables)}
UI Style: {ui_spec.color_palette}

Generate:
1. `backend_main_py`: Production-grade FastAPI app using `from nexus.api import create_nexus_app` and `from nexus.ai import GeminiClient`.
2. `backend_models_py`: Pydantic input/output schemas and SQLAlchemy entities.
3. `frontend_app_tsx`: Modern React + Tailwind interface consuming the API endpoints.
4. `frontend_api_client_ts`: Clean TypeScript fetch helper with type definitions.
"""
        system = "You are a pragmatic, master Full-Stack Engineer writing clean, production-grade Python and TypeScript."
        return self.provider.structured(prompt, FullStackSpecification, system_instruction=system)
